import sharp from "sharp";
export { sharp };
export async function fromFile(file) {
    return sharp(new Uint8Array(await file.arrayBuffer()));
}
export const inputFormats = [
    "avif",
    "gif",
    "heif",
    "jpeg",
    "jp2",
    "jxl",
    "png",
    "tiff",
    "raw",
    "webp",
];
export const outputFormats = ["avif", "gif", "jpeg", "png", "tiff", "raw", "webp"];
const extensionAliases = new Map([
    ["tif", "tiff"],
    ["jpg", "jpeg"],
]);
export function getInputFormat(name) {
    const extension = name.split(".").pop()?.toLowerCase();
    if (extension) {
        return (extensionAliases.get(extension) ?? inputFormats.includes(extension))
            ? extension
            : undefined;
    }
}
export function getOutputFormat(name) {
    const extension = name.split(".").pop()?.toLowerCase();
    if (extension) {
        return (extensionAliases.get(extension) ?? outputFormats.includes(extension))
            ? extension
            : undefined;
    }
}
